"""Copy the landing page's POSTS and CAT into assets/posts-data.js so article pages can show
"Keep reading" with the same posts, art and categories as the gallery.

Run from the repo root after editing POSTS in index.html:  python3 _build/posts_data.py
"""
import json
import re

src = open("index.html", encoding="utf-8").read()
posts = json.loads(re.search(r"const POSTS=(\[\[.*?\]\])\.map\(", src, re.S).group(1))
cat = dict(re.findall(r"(\w+):'([^']*)'", re.search(r"const CAT=\{(.*?)\};", src).group(1)))

out = (
    "/* generated by _build/posts_data.py from index.html; don't edit by hand */\n"
    f"window.PRIVY_CAT={json.dumps(cat, ensure_ascii=False)};\n"
    f"window.PRIVY_POSTS={json.dumps(posts, ensure_ascii=False)};\n"
)
open("assets/posts-data.js", "w", encoding="utf-8").write(out)
print(f"wrote assets/posts-data.js: {len(posts)} posts")
